import {accountReady} from './account-client.js';
const contributor=location.pathname.startsWith('/recipes/contribute'),namespace=contributor?'ezeats-user:':'ezeats-owner:';
let retryKey=null;
const $=id=>document.getElementById(id),el=(tag,value)=>{const n=document.createElement(tag);if(value!==undefined)n.textContent=value;return n;};
