input(grid,'title','Recipe title',{required:true});input(grid,'id','Stable recipe ID',{value:namespace,required:true,max:100});input(grid,'author','Public author name');
f.append(el('p',`Use ${namespace}recipe-name. The ID cannot change after creation.`));input(f,'description','Description',{type:'textarea',max:1200});
