f=group('Ingredients');const ingredientContainer=el('div');f.append(ingredientContainer,button('Add ingredient',()=>{addIngredient();touch();}));
function addIngredient(value={}){const row=el('div');row.className='ingredient-row';const item={row};for(const [key,label,max] of [['quantity','Quantity',40],['unit','Unit',40],['name','Ingredient',200],['notes','Preparation notes',500]]){const l=el('label',label),n=el('input');n.value=value[key]||'';n.maxLength=max;l.append(n);row.append(l);item[key]=n;}const remove=button('Remove',()=>{ingredients.splice(ingredients.indexOf(item),1);row.remove();touch();});remove.setAttribute('aria-label','Remove ingredient');row.append(remove);ingredientContainer.append(row);ingredients.push(item);}
f=group('Cooking directions');f.append(el('p','Use complete, practical steps. Include safe temperatures and handling where relevant.'));const stepContainer=el('div');f.append(stepContainer,button('Add step',()=>{addStep();touch();}));
function stepLabels(){steps.forEach((s,i)=>{s.label.firstChild.textContent=`Step ${i+1}`;s.up.disabled=busy||i===0;s.down.disabled=busy||i===steps.length-1;s.up.setAttribute('aria-label',`Move step ${i+1} up`);s.down.setAttribute('aria-label',`Move step ${i+1} down`);s.remove.setAttribute('aria-label',`Remove step ${i+1}`);});}
function addStep(value=''){const row=el('div');row.className='step-row';const label=el('label','Step'),area=el('textarea');area.rows=3;area.maxLength=2500;area.value=value;label.append(area);const s={row,label,area};const move=delta=>{const i=steps.indexOf(s),j=i+delta;if(j<0||j>=steps.length)return;[steps[i],steps[j]]=[steps[j],steps[i]];stepContainer.replaceChildren(...steps.map(x=>x.row));stepLabels();area.focus();touch();};s.up=button('Move up',()=>move(-1));s.down=button('Move down',()=>move(1));s.remove=button('Remove',()=>{steps.splice(steps.indexOf(s),1);row.remove();stepLabels();touch();});const buttons=el('div');buttons.className='row-buttons';buttons.append(s.up,s.down,s.remove);row.append(label,buttons);steps.push(s);stepContainer.append(row);stepLabels();}
f=group('Classification');grid=el('div');grid.className='field-grid';f.append(grid);input(grid,'cuisine','Cuisine / inspired by',{max:150});input(grid,'difficulty','Difficulty',{options:['easy','moderate','advanced']});f.append(el('h3','Meal types'));checks(f,'mealTypes',types);f.append(el('h3','Dietary claims'));checks(f,'dietTags',diets);f.append(el('h3','Known major allergens'));checks(f,'knownAllergens',allergens);f.append(el('p','Claims are unverified. An empty allergen list never means allergen-safe. Check every ingredient and packaged product.'));
f=group('Picker metadata');checks(f,'moods',['comfort','fresh','bold']);grid=el('div');grid.className='field-grid';f.append(grid);input(grid,'heat','Heat: 0 mild, 1 medium, 2 spicy',{options:['0','1','2']});input(grid,'familiarity','Familiarity',{options:['familiar','adventurous']});input(grid,'budget','Budget category',{options:['budget','everyday','treat']});input(grid,'estimatedCost','Estimated cost per person (optional)',{type:'number'});input(grid,'currency','Currency',{options:['USD','CAD']});
f=group('Safety and suitability evidence');input(f,'safetyEvidence','Food-safety evidence and handling notes',{type:'textarea',max:4000});input(f,'dietEvidence','Ingredient evidence for dietary claims',{type:'textarea',max:3000});input(f,'allergenEvidence','Allergen assessment, unknowns and package-label checks',{type:'textarea',max:3000});f.append(el('p','Evidence is recorded as claimed or unknown. Approval is not kitchen testing, medical advice or an allergy-safety guarantee.'));
f=group('Rights and private notes');const copyright=el('label');copyright.className='check-label';controls.copyrightConfirmed=el('input');controls.copyrightConfirmed.type='checkbox';copyright.append(controls.copyrightConfirmed,el('span',contributor?'I confirm this recipe is original or I have permission to submit and allow EZEATS to display it.':'I confirm this is original EZEATS-owned work and I have the right to publish it.'));f.append(copyright);input(f,'copyrightStatement','Original-work / copyright statement',{type:'textarea',max:2000});input(f,'privateNotes','Private draft notes (never public)',{type:'textarea',max:4000});
input(f,'rightsBasis','Copyright basis',{options:['original-work','permission']});input(f,'sourceUrl','Original source URL (HTTPS, if applicable)',{max:1000});input(f,'sourceAttribution','Source attribution (if applicable)',{max:500});
if(contributor){controls.privateNotes.parentElement.hidden=true;f.append(el('p','Published recipes do not disappear automatically when you delete your sign-in account. Contact an owner about removal or attribution changes. Withdrawal preserves private revision history. No copyright ownership transfer is claimed.'));}
f=group('Image rights — uploads disabled');grid=el('div');grid.className='field-grid';f.append(grid);input(grid,'imageOwnership','Ownership',{options:['none','author-owned','licensed','unknown']});input(grid,'imageOwner','Image owner');input(grid,'imageLicenseStatus','License status',{options:['not-applicable','unknown','permission-confirmed','not-permitted']});input(f,'imageLicenseReference','License reference (private)',{max:1000});f.append(el('p','No image file or URL is accepted in this phase.'));
function content(){const c={};for(const [key,n] of Object.entries(controls)){if(key.startsWith('image'))continue;c[key]=Array.isArray(n)?n.filter(x=>x.checked).map(x=>x.value):n.type==='checkbox'?n.checked:n.value.trim();}for(const key of ['servings','preparationMinutes','cookingMinutes','totalMinutes','estimatedCost'])c[key]=c[key]===''?null:Number(c[key]);c.heat=Number(c.heat);c.ingredients=ingredients.map(i=>Object.fromEntries(['quantity','unit','name','notes'].map(k=>[k,i[k].value.trim()])));c.steps=steps.map(s=>s.area.value.trim());c.imageRights={ownership:controls.imageOwnership.value,owner:controls.imageOwner.value.trim(),licenseStatus:controls.imageLicenseStatus.value,licenseReference:controls.imageLicenseReference.value.trim()};return c;}
function reset(c={}){for(const [key,n] of Object.entries(controls)){if(Array.isArray(n))n.forEach(x=>x.checked=(c[key]||[]).includes(x.value));else if(n.type==='checkbox')n.checked=!!c[key];else if(n.tagName==='SELECT')n.value=c[key]??n.options[0].value;else n.value=c[key]??'';}controls.id.value=c.id||namespace;controls.id.readOnly=!!record;for(const [key,field] of [['imageOwnership','ownership'],['imageOwner','owner'],['imageLicenseStatus','licenseStatus'],['imageLicenseReference','licenseReference']])controls[key].value=c.imageRights?.[field]??(controls[key].tagName==='SELECT'?controls[key].options[0].value:'');ingredients.length=0;steps.length=0;ingredientContainer.replaceChildren();stepContainer.replaceChildren();(c.ingredients?.length?c.ingredients:[{}]).forEach(addIngredient);(c.steps?.length?c.steps:['']).forEach(addStep);dirty=false;$('public-preview').hidden=true;$('decision-notes').value='';$('contributor-message').value='';}
function preview(c,target,title='Recipe preview'){
 target.replaceChildren();target.className='recipe-preview';target.append(el('h3',title),el('h4',c.title||'Untitled recipe'),el('p',c.description),el('p',`${c.servings??'Unknown'} servings · Prep ${c.preparationMinutes??'?'} min · Cook ${c.cookingMinutes??'?'} min · Total ${c.totalMinutes??'?'} min`),el('p',`${c.cuisine} · ${c.mealTypes.join(', ')} · ${c.difficulty}`),el('p',`Dietary claims: ${c.dietTags.join(', ')||'None supplied'}. Known allergens: ${c.knownAllergens.join(', ')||'Unknown / none supplied'}.`),el('p','Suitability unverified. Check ingredient labels, substitutions and cross-contact. Not kitchen-tested or an allergy-safety guarantee.'));
 if(c.estimatedCost!==null)target.append(el('p',`Estimated ${c.currency} ${c.estimatedCost} per serving; actual costs vary.`));
 target.append(el('h4','Ingredients'));const ul=el('ul');for(const i of c.ingredients)ul.append(el('li',`${i.quantity} ${i.unit} ${i.name}${i.notes?' — '+i.notes:''}`));target.append(ul,el('h4','Cooking instructions'));const ol=el('ol');c.steps.forEach(s=>ol.append(el('li',s||'Incomplete step')));target.append(ol,el('p',`${c.id?.startsWith('ezeats-user:')?'Contributor recipe':'Original EZEATS recipe'} by ${c.author||'Author not supplied'}. No image. No external reuse license granted.`));target.hidden=false;
}
function detail(){controls.rightsBasis.parentElement.hidden=!contributor&&record?.origin!=='user-submitted';copyright.lastChild.textContent=contributor?'I confirm this recipe is original or I have permission to submit and allow EZEATS to display it.':record?.origin==='user-submitted'?'Contributor copyright confirmation (review the recorded attestation below).':'I confirm this is original EZEATS-owned work and I have the right to publish it.';const latest=record?.revisions.at(-1);$('editor-heading').textContent=record?'Edit recipe':'Create recipe';$('contributor-message').parentElement.hidden=contributor||record?.origin!=='user-submitted';$('decision-notes').parentElement.hidden=contributor;
 $('revision-state').textContent=record?`${record.origin} · ${record.removed_at?'removed':record.latest_status} · revision ${record.latest_version} · ${record.published_version?'Published version '+record.published_version:'Not published'} · ${record.updated_at}${!contributor&&record.origin==='user-submitted'?' · Submitting account: '+record.submitting_account_id:''}`:contributor?'Your private contributor draft. Only you and authorized owners can read it.':'A private first-party draft. Save now and finish later.';reset(latest?.document.content);$('save-recipe').textContent=record?.published_version?'Save pending revision':'Save draft';$('editor-panel').hidden=false;$('review-actions').hidden=!record||!!record.removed_at;$('recipe-form').hidden=!!record?.removed_at;
 $('revision-comparison').hidden=!record;const compare=$('comparison');compare.replaceChildren();compare.className='comparison-grid';if(record){const published=record.revisions.find(r=>r.version===record.published_version);const left=el('div'),right=el('div');published?preview(published.document.content,left,'Published version '+published.version):left.append(el('p','No published version.'));preview(latest.document.content,right,'Saved candidate '+latest.version);compare.append(left,right);const privateDiff=el('details');privateDiff.append(el('summary','Private field-by-field revision comparison'));for(const key of Object.keys(latest.document.content)){const before=published?.document.content[key],after=latest.document.content[key];if(JSON.stringify(before)!==JSON.stringify(after))privateDiff.append(el('p',`${key}: ${JSON.stringify(before)??'Not published'} → ${JSON.stringify(after)}`));}compare.append(privateDiff);}
 $('open-version-form').hidden=contributor||!record;$('older-version').hidden=true;$('earlier-events').hidden=contributor||!record?.nextBefore;const history=$('revision-history');history.replaceChildren();for(const r of record?.revisions||[]){const box=el('details');box.className='private-history';box.append(el('summary',`Version ${r.version} · ${r.status} · ${r.created_at} · ${r.document.content.author||'Author not supplied'}`));const p=el('div');preview(r.document.content,p,'Version '+r.version);box.append(p,el('p',`Private notes: ${r.document.content.privateNotes||'None'}`),el('p',`Private rights/evidence: ${JSON.stringify({attestation:r.document.attestation,evidence:r.document.evidence,imageRights:r.document.content.imageRights})}`));history.append(box);}
 for(const m of record?.changeRequests||[])history.append(el('p',`Owner message for version ${m.version}: ${m.message}`));
 for(const e of record?.events||[])history.append(el('p',`${e.created_at} · ${e.action} · version ${e.version}${contributor?'':' · actor '+e.actor_account_id}${e.private_notes?' · '+e.private_notes:''}`));syncActions();}
function syncActions(){const buttons=$('decision-buttons');buttons.replaceChildren();if(record&&!record.removed_at){const ownerMap={draft:['submit','reject','remove'],pending:['approve','approve-and-publish','request-changes','reject','remove'],approved:['publish','request-changes','reject','remove'],published:['remove'],'changes-requested':['submit','reject','remove'],rejected:['remove']};const map=contributor?{draft:['submit','withdraw'],'changes-requested':['submit','withdraw'],rejected:['withdraw'],published:[],pending:[],approved:[]}:ownerMap;const labels={withdraw:'Withdraw draft',submit:'Submit for review',approve:'Approve',publish:'Publish approved version','approve-and-publish':'Approve and publish','request-changes':'Request changes',reject:'Reject',remove:'Remove recipe'};for(const action of map[record.latest_status]||[]){const b=button(labels[action],()=>run(async()=>{if(action==='remove'&&!confirm('Withdraw this recipe? Its private revision and decision history will be preserved.'))return;const data=await request({body:{action,id:record.id,expectedLock:record.lock_version,...(contributor?{}:{notes:$('decision-notes').value,...(record.origin==='user-submitted'?{contributorMessage:$('contributor-message').value}:{})})}});record=data.record;detail();await list();message(contributor?(action==='submit'?'Submitted for owner review. This revision is now read-only.':'Draft withdrawn. Private history retained.'):'Decision saved. Public picker remains unchanged.');}));b.disabled=dirty||busy;buttons.append(b);}}
 $('previous-page').disabled=busy||offset===0;$('next-page').disabled=busy||nextOffset===null;const readOnly=contributor&&record&&['pending','approved'].includes(record.latest_status);$('recipe-fields').querySelectorAll('input,select,textarea,button').forEach(n=>n.disabled=busy||readOnly);$('save-recipe').disabled=busy||readOnly;stepLabels();if(readOnly)stepContainer.querySelectorAll('button').forEach(n=>n.disabled=true);}
async function list(){const q=new URLSearchParams(contributor?undefined:new FormData($('catalog-filters')));q.set('offset',offset);if(!contributor)q.set('limit',20);const data=await request({query:'?'+q});nextOffset=data.nextOffset;$('workspace').hidden=false;$('workspace-signin').hidden=true;$('workspace-retry').hidden=true;const list=$('recipe-list');list.replaceChildren();if(!data.items.length)list.append(el('p','No recipes match. Create your first draft or change the filters.'));for(const r of data.items){const card=el('article');card.className='catalog-card';card.append(el('h2',r.title),el('p',`${r.origin} · ${r.removed_at?'removed':r.latest_status} · ${r.author||'Author not supplied'}`),el('p',`${r.id} · Created ${r.created_at} · Updated ${r.updated_at}`),el('p',r.published_version?`Published version ${r.published_version} (not in public picker)`:'Not published'));card.append(button('Open recipe',()=>run(async()=>{if(!leave())return;const loaded=await request({query:'?id='+encodeURIComponent(r.id)});record=loaded.record;detail();if(!contributor&&loaded.candidates?.length)$('revision-state').append(el('p','Possible duplicates (editorial review only): '+loaded.candidates.map(x=>x.id+' — '+x.title).join('; ')));$('editor-heading').focus();})));list.append(card);}syncActions();}
function leave(){return !dirty||confirm('Discard unsaved edits? Saved revisions will remain.');}
for(const [id,values] of [['filter-meal',types],['filter-diet',diets]])for(const value of values){const o=el('option',value);o.value=value;$(id).append(o);}
$('recipe-form').addEventListener('input',touch);$('recipe-form').addEventListener('change',touch);$('recipe-form').addEventListener('submit',event=>{event.preventDefault();run(async()=>{const c=content(),body=record?{action:'save',id:record.id,expectedLock:record.lock_version,content:c}:{action:'create',id:c.id,content:c};record=(await request({body})).record;detail();await list();message(contributor&&record.latest_status==='pending'?'Revision submitted for owner review. The published version is unchanged.':'Recipe saved. You can safely return and resume editing.');});});
$('create-recipe').addEventListener('click',()=>{if(!leave())return;record=null;detail();$('editor-heading').focus();});$('close-editor').addEventListener('click',()=>{if(!leave())return;dirty=false;$('editor-panel').hidden=true;$('create-recipe').focus();});$('preview-recipe').addEventListener('click',()=>{preview(content(),$('public-preview'));$('public-preview').tabIndex=-1;$('public-preview').focus();});$('catalog-filters').addEventListener('submit',e=>{e.preventDefault();offset=0;run(list);});$('previous-page').addEventListener('click',()=>{offset=Math.max(0,offset-20);run(list);});$('next-page').addEventListener('click',()=>{if(nextOffset!==null){offset=nextOffset;run(list);}});$('workspace-retry').addEventListener('click',()=>run(async()=>{await list();message('Owner recipe workspace ready.');}));window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
$('open-version-form').addEventListener('submit',e=>{e.preventDefault();if(!record)return;run(async()=>{const data=await request({query:'?id='+encodeURIComponent(record.id)+'&version='+encodeURIComponent($('open-version').value)});const target=$('older-version');preview(data.revision.document.content,target,'Saved version '+data.revision.version);target.append(el('p','Private revision record: '+JSON.stringify(data.revision.document)));});});
$('earlier-events').addEventListener('click',()=>run(async()=>{if(!record?.nextBefore)return;const data=await request({query:'?id='+encodeURIComponent(record.id)+'&before='+record.nextBefore});const block=el('div');for(const e of data.events)block.append(el('p',`${e.created_at} · ${e.action} · version ${e.version}${contributor?'':' · actor '+e.actor_account_id}${e.private_notes?' · '+e.private_notes:''}`));$('revision-history').prepend(block);record.nextBefore=data.nextBefore;$('earlier-events').hidden=!data.nextBefore;}));
if(contributor){$('catalog-filters').hidden=true;$('workspace-notice').textContent='Invitation-only contributor beta. Drafts are private. Submitted versions are read-only until moderation. Claims are unverified; check food safety, package labels and cross-contact. Uploads are disabled.';}
await run(async()=>{await list();message(contributor?'Contributor workspace ready.':'Owner recipe workspace ready.');});
if(clerk){let sessionId=clerk.session?.id;clerk.addListener(({session})=>{if(session?.id!==sessionId){sessionId=session?.id;record=null;dirty=false;$('workspace').hidden=true;$('editor-panel').hidden=true;message('Your account session changed. Reload to verify workspace access.');$('workspace-retry').hidden=false;}});}
